:root{--nacht:#16233a;--nacht-2:#22324f;--warmwit:#fffdf7;--geel:#ffd84d;--lucht:#dceeff;--slate:#667085;--soft:#f5f7fa;--wit:#fff;--line:#e4e7ec;--line-strong:#cfd5df;--error:#b42318;--success:#067647;--font-display:var(--font-manrope),system-ui,sans-serif;--font-body:var(--font-inter),system-ui,sans-serif;--container:1200px;--gutter:clamp(20px,5vw,32px);--section:clamp(64px,9vw,120px);--radius:16px;--radius-btn:12px;--ease:cubic-bezier(.22,1,.36,1);--t-ui:220ms;--t-reveal:520ms;--header-h:72px}*,*::before,*::after{box-sizing:border-box}html{-webkit-text-size-adjust:100%;scroll-padding-top:calc(var(--header-h) + 16px)}body{margin:0;background:var(--warmwit);color:var(--nacht);font-family:var(--font-body);font-size:16px;line-height:1.6;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased;overflow-x:clip;overflow-wrap:break-word}h1,h2,h3{hyphens:auto;-webkit-hyphens:auto}@media(min-width:768px){body{font-size:17px}}img,svg{display:block;max-width:100%}a{color:inherit}button,input,select,textarea{font:inherit;color:inherit}p{margin:0 0 1em}p:last-child{margin-bottom:0}h1,h2,h3,h4,.display{font-family:var(--font-display);font-weight:750;letter-spacing:-.025em;margin:0 0 .5em;text-wrap:balance}.display{font-size:clamp(2.5rem,1.6rem + 3.9vw,4rem);line-height:1.06;letter-spacing:-.035em;font-weight:800}h1{font-size:clamp(2.375rem,1.9rem + 2.1vw,3.25rem);line-height:1.08;letter-spacing:-.03em}h2{font-size:clamp(2rem,1.7rem + 1.3vw,2.5rem);line-height:1.12}h3{font-size:clamp(1.375rem,1.25rem + .6vw,1.75rem);line-height:1.2;letter-spacing:-.015em}h4{font-size:1.125rem;line-height:1.3;letter-spacing:-.01em;font-weight:700}.intro{font-size:clamp(1.125rem,1.05rem + .35vw,1.25rem);line-height:1.55;color:var(--nacht);max-width:38em}.muted{color:var(--slate)}.small{font-size:.875rem}.container{width:100%;max-width:calc(var(--container) + 2 * var(--gutter));margin:0 auto;padding-inline:var(--gutter)}.section{padding-block:var(--section)}.section--lucht{background:va