k:hover{text-decoration-color:currentColor}.logo{display:inline-flex;align-items:center;text-decoration:none;color:inherit}.wordmark{font-family:var(--font-display);font-weight:800;letter-spacing:-.045em;font-size:1.5rem;line-height:1;white-space:nowrap;display:inline-flex;align-items:baseline}.wordmark__dag{position:relative;padding-bottom:.2em;margin-bottom:-.2em;-webkit-mask-image:linear-gradient(to bottom,#000 0 60%,transparent 60% 63.75%,#000 63.75%);mask-image:linear-gradient(to bottom,#000 0 60%,transparent 60% 63.75%,#000 63.75%)}.wordmark__space{width:.24em;display:inline-block}.header{position:sticky;top:0;z-index:50;background:color-mix(in srgb,var(--warmwit) 92%,transparent);backdrop-filter:saturate(1.4) blur(10px);-webkit-backdrop-filter:saturate(1.4) blur(10px);border-bottom:1px solid transparent;transition:border-color var(--t-ui)}.header[data-scrolled=true]{border-bottom-color:var(--line)}.header__inner{height:var(--header-h);display:flex;align-items:center;justify-content:space-between;gap:24px}.header__nav{display:none}.header__nav ul{display:flex;gap:4px;list-style:none;margin:0;padding:0}.header__nav a{display:inline-flex;align-items:center;min-height:44px;padding:0 14px;border-radius:10px;text-decoration:none;font-weight:500;font-size:15px;color:var(--nacht);position:relative}.header__nav a::after{content:"";position:absolute;left:14px;right:14px;bottom:8px;height:2px;background:var(--geel);transform:scaleX(0);transform-origin:left;transition:transform var(--t-ui) var(--ease)}.header__nav a:hover::after,.header__nav a[aria-current=page]::after{transform:scaleX(1)}.header__cta{display:none}.header__cta .btn{min-height:44px;font-size:15px}@media(min-width:960px){.header__nav{display:block}.header__cta{display:block}.menu-toggle{display:none!important}}.menu-toggle{display:inline-flex;align-items:center;gap:10px;min-height:44px;padding:0 14px;background:transparent;border:1.5px solid var(--line-strong);border-radius:10px;cursor:pointer;font-weight: