rice{font-family:var(--font-display);font-size:2.25rem;font-weight:800;letter-spacing:-.035em;line-height:1;margin:8px 0 22px;padding-bottom:22px;border-bottom:1px solid var(--line)}.price-card .checklist{margin-bottom:28px}.price-card .btn{margin-top:auto}.faq{border-top:1px solid var(--line-strong);max-width:52rem}.faq details{border-bottom:1px solid var(--line-strong)}.faq summary{list-style:none;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:24px;padding:22px 0;min-height:56px;font-family:var(--font-display);font-weight:700;font-size:1.125rem}.faq summary::-webkit-details-marker{display:none}.faq__answer{padding:0 0 24px;max-width:44em;color:var(--slate)}.page-hero{padding-top:clamp(40px,7vw,88px);padding-bottom:clamp(40px,6vw,72px);border-bottom:1px solid var(--line);position:relative}.page-hero::after{content:"";position:absolute;left:var(--gutter);bottom:-2px;width:64px;height:3px;background:var(--geel)}.page-hero .intro{margin-top:16px}.page-hero .btn-row{margin-top:28px}.split{display:grid;gap:40px;align-items:start}@media(min-width:900px){.split{grid-template-columns:1fr 1fr;gap:72px}}.panel{background:var(--wit);border:1px solid var(--line);border-radius:var(--radius);padding:clamp(24px,3vw,36px)}.cols-2{display:grid;gap:32px}@media(min-width:860px){.cols-2{grid-template-columns:1fr 1fr;gap:56px}}.prose{max-width:44rem}.form{display:grid;gap:20px}.form__row{display:grid;gap:20px}@media(min-width:640px){.form__row{grid-template-columns:1fr 1fr}}.field{display:grid;gap:8px}.input,.textarea{width:100%;min-height:50px;padding:12px 14px;background:var(--wit);border:1.5px solid var(--line-strong);border-radius:10px;font-size:16px}.textarea{min-height:128px;resize:vertical;line-height:1.5}.contact-grid{display:grid;gap:40px}@media(min-width:960px){.contact-grid{grid-template-columns:1fr 1.4fr;gap:72px}}.footer{background:var(--nacht);color:var(--wit);padding-block:64px 32px;position:relative}.footer::before{content:"";position:a